'use strict';
(() => {
const D=window.ALSACE_DATA, L=window.ALSACE_SITES, KEY='alsace-atlas-v3', OLD='alsace-checklist-v2';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const uid=()=>crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random().toString(36).slice(2)}`;
const today=()=>new Date().toISOString().slice(0,10);
const empty=()=>({version:4,personalSites:[],targets:[],excluded:[],producerSites:[],producers:[],wines:[],comparisons:[],explore:[],legacy:{checked:{},notes:{}}});
let state=empty(), tab='atlas',query='', region='all',kind='all',soil='all',coverage='all',wineStatus='all',producerRegion='all',producerStatus='all', mxMode='grape-geo',mxArea='all',mxGrape='Riesling',mxSiteArea='all', storageWritable=true;
const baseSites=[...D.crus,...D.places,...L.lieux];
let sites=[...baseSites], siteById=new Map(sites.map(s=>[s.id,s]));
function rebuildSites(){sites=[...baseSites,...state.personalSites];siteById=new Map(sites.map(s=>[s.id,s]))}
const topicById=new Map(D.topics.map(t=>[t.id,t]));
const geoCats=L.geologyCategories, geoById=new Map(geoCats.map(g=>[g.id,g]));
const geoName=id=>id?(geoById.get(id)?.name||id):'Unknown geology';
const geoShort=id=>id?(geoById.get(id)?.short||id):'Unknown';
const siteKinds=['Grand Cru','Area / village','Clos','Lieu-dit'];
function siteGeology(s){if(!s)return '';return s.geology||L.soilToGeology[s.soil]||''}
function geologyBasis(s){return s.basis||(s.kind==='Grand Cru'?'CIVA whole-site reference wording':s.id?.startsWith('psite-')?'Personal entry':'')}
const grapes=['Riesling','Gewurztraminer','Pinot Gris','Pinot Blanc','Auxerrois','Muscat','Sylvaner','Pinot Noir','Savagnin Rose','Chasselas','Chardonnay','Blend / other'];
const grapeTopics={'Riesling':'ries-base','Gewurztraminer':'gewurz-base','Pinot Gris':'pg-base','Pinot Blanc':'pb-base','Auxerrois':'aux-base','Muscat':'muscat-base','Sylvaner':'sylv-base','Savagnin Rose':'klevener','Chasselas':'chasselas','Chardonnay':'chardonnay'};
const singleGrapes=grapes.filter(g=>g!=='Blend / other');
// Coverage resolution: a record counts toward an exact grape x geology x area combination only when each axis is supported.
const wineGrapeKey=w=>!w.grape?'':w.grape==='Blend / other'?'blend':w.grape;
const wineArea=w=>{if(w.multiOrigin)return '';const s=siteById.get(w.site);return s?s.region:(w.originRegion||'')};
const wineGeo=w=>{if(w.multiOrigin)return '';if(w.parcelGeology)return w.parcelGeology;const s=siteById.get(w.site);return s?siteGeology(s):''};
const comboKey=(g,geo,area)=>g+'|'+geo+'|'+area;
const grapeLabel=g=>g==='blend'?'Blend / field blend':g;
function notify(s){$('#dialog-notice').textContent=$('#editor').open?s:'';$('#notice').textContent=s;$('#notice').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#notice').classList.remove('show'),6500)}
function save(){if(!storageWritable){notify('Browser storage is unavailable. Export a backup before leaving.');return false;}try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch(e){notify('Could not save in this browser. Export a backup before leaving.');return false}}
function str(x,max=12000){if(x==null)return '';if(typeof x!=='string'||x.length>max)throw Error('Invalid text field');return x}
function strings(a){if(a==null)return [];if(!Array.isArray(a)||a.length>1000||a.some(x=>typeof x!=='string'||x.length>300))throw Error('Invalid selection');return [...new Set(a)]}
function safeUrl(s){try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}}
function legacyValid(x){if(!x||typeof x!=='object'||Array.isArray(x))throw Error('Invalid legacy data');const out={checked:{},notes:{}};for(const key of ['checked','notes']){const m=x[key]||{};if(typeof m!=='object'||Array.isArray(m)||Object.keys(m).length>10000)throw Error('Invalid legacy data');for(const [k,v] of Object.entries(m)){if(['__proto__','constructor','prototype'].includes(k))throw Error('Invalid key');if(key==='notes')out.notes[k]=str(v);else if(v===1||v===true)out.checked[k]=1;else if(v!==0&&v!==false)throw Error('Invalid check');}}return out}
function validate(x){
 if(x?.version!==3&&x?.version!==4)throw Error('Unsupported backup version');
 if(!Array.isArray(x.wines)||!Array.isArray(x.comparisons)||x.wines.length>10000||x.comparisons.length>10000)throw Error('Invalid backup');
 const out=empty();out.explore=strings(x.explore);out.legacy=legacyValid(x.legacy||{});
 if(x.personalSites!=null&&!Array.isArray(x.personalSites))throw Error('Invalid personal vineyards');
 if((x.personalSites||[]).length>10000)throw Error('Too many personal vineyards');
 out.personalSites=(x.personalSites||[]).map(s=>{if(!s||typeof s!=='object')throw Error('Invalid personal vineyard');const n={};for(const k of ['id','name','kind','village','region','parent','geology','soil','basis','source','notes'])n[k]=str(s[k]);if(!n.id.startsWith('psite-')||!n.name.trim()||!n.village.trim()||!D.regions.some(r=>r.id===n.region)||!siteKinds.includes(n.kind)||n.geology&&!geoById.has(n.geology)||n.source&&!safeUrl(n.source))throw Error('Invalid personal vineyard details');return n});
 if(new Set(out.personalSites.map(s=>s.id)).size!==out.personalSites.length)throw Error('Duplicate vineyard IDs');
 const siteMap=new Map([...baseSites,...out.personalSites].map(s=>[s.id,s]));
 for(const s of out.personalSites)if(s.parent&&!siteMap.has(s.parent))throw Error('Unknown parent site');
 const validCombo=k=>{const p=String(k).split('|');if(p.length!==3)return false;const [g,geo,area]=p;return (g==='blend'||singleGrapes.includes(g))&&(geo===''||geoById.has(geo))&&(area==='any'||D.regions.some(r=>r.id===area)||(area.startsWith('site:')&&siteMap.has(area.slice(5))))};
 out.targets=strings(x.targets);if(out.targets.some(k=>!validCombo(k)))throw Error('Invalid coverage target');
 if(x.excluded!=null&&!Array.isArray(x.excluded))throw Error('Invalid exclusions');
 if((x.excluded||[]).length>10000)throw Error('Too many exclusions');
 out.excluded=(x.excluded||[]).map(e=>{if(!e||typeof e!=='object')throw Error('Invalid exclusion');const n={key:str(e.key),reason:str(e.reason)};if(!validCombo(n.key)||!n.reason.trim())throw Error('A not-applicable mark needs a stated reason');return n});
 if(new Set(out.excluded.map(e=>e.key)).size!==out.excluded.length)throw Error('Duplicate exclusions');
 if(x.producers!=null&&!Array.isArray(x.producers))throw Error('Invalid personal producers');
 if((x.producers||[]).length>10000)throw Error('Too many personal producers');
 out.producers=(x.producers||[]).map(p=>{if(!p||typeof p!=='object')throw Error('Invalid producer');const n={};for(const k of ['id','name','village','region','source','notes'])n[k]=str(p[k]);if(!n.id.startsWith('personal-')||!n.name.trim()||!n.village.trim()||!D.regions.some(r=>r.id===n.region)||n.source&&!safeUrl(n.source))throw Error('Invalid producer details');return n});
 if(new Set(out.producers.map(p=>p.id)).size!==out.producers.length)throw Error('Duplicate producer IDs');
 const producerIds=new Set([...window.ALSACE_PRODUCERS.entries,...out.producers].map(p=>p.id));
 if(x.producerSites!=null&&!Array.isArray(x.producerSites))throw Error('Invalid origin links');
 if((x.producerSites||[]).length>10000)throw Error('Too many origin links');
 out.producerSites=(x.producerSites||[]).map(l=>{if(!l||typeof l!=='object')throw Error('Invalid origin link');const n={};for(const k of ['producerId','site','relationship','evidence'])n[k]=str(l[k]);if(!producerIds.has(n.producerId)||!siteMap.has(n.site)||!['wine','grower'].includes(n.relationship)||!n.evidence.trim())throw Error('Origin link needs producer, place and evidence');return n});
 if(new Set(out.producerSites.map(l=>l.producerId+'|'+l.site)).size!==out.producerSites.length)throw Error('Duplicate origin links');
 const fields=['producerId','id','status','producer','cuvee','vintage','date','cellar','origin','originEvidence','grape','designation','site','region','venue','sugar','alcohol','vessel','notes','seller','country','url','price','checkedDate','availability','bottleRef','originRegion','parcelGeology','parcelGeologyEvidence','blendNote','multiOrigin'];
 out.wines=x.wines.map(w=>{if(!w||typeof w!=='object')throw Error('Invalid wine');const n={};fields.forEach(k=>n[k]=str(w[k]));n.topics=strings(w.topics);n.blendGrapes=strings(w.blendGrapes);if(n.producerId&&!producerIds.has(n.producerId))throw Error('Unknown linked producer');if(!n.id||!n.producer||!['tasted','wishlist'].includes(n.status))throw Error('Invalid wine record');if(n.site&&!n.originEvidence.trim())throw Error('Site needs origin evidence');if(n.site&&!siteMap.has(n.site))throw Error('Unknown site');if(n.originRegion&&!D.regions.some(r=>r.id===n.originRegion))throw Error('Unknown origin area');if(n.parcelGeology&&!geoById.has(n.parcelGeology))throw Error('Unknown geology category');if(n.parcelGeology&&!n.parcelGeologyEvidence.trim())throw Error('A parcel-level geology correction needs a source');if(n.blendGrapes.some(g=>!singleGrapes.includes(g)))throw Error('Unknown blend grape');if(n.multiOrigin&&(n.site||n.originRegion||n.parcelGeology))throw Error('A multi-origin wine cannot claim a single site, area or geology');if(n.topics.some(t=>!topicById.has(t)))throw Error('Unknown learning topic');if(n.url&&!safeUrl(n.url))throw Error('Invalid source URL');return n});
 const ids=new Set(out.wines.map(w=>w.id));if(ids.size!==out.wines.length)throw Error('Duplicate wine IDs');
 out.comparisons=x.comparisons.map(c=>{if(!c||typeof c!=='object')throw Error('Invalid comparison');const n={id:str(c.id),exercise:str(c.exercise),date:str(c.date),notes:str(c.notes),wines:strings(c.wines)};if(!n.id||!D.comparisons.some(e=>e.id===n.exercise)||!n.notes.trim()||n.wines.length<2||n.wines.some(id=>!out.wines.some(w=>w.id===id&&w.status==='tasted')))throw Error('Comparison needs two tasted records');return n});
 if(new Set(out.comparisons.map(c=>c.id)).size!==out.comparisons.length)throw Error('Duplicate comparison IDs');return out;
}
function tasted(){return state.wines.filter(w=>w.status==='tasted')}
function wineTopics(w){return [...new Set([...(w.topics||[]),...(grapeTopics[w.grape]?[grapeTopics[w.grape]]:[])])]}
function siteWines(id){return tasted().filter(w=>w.site===id)}
function topicWines(id){return tasted().filter(w=>wineTopics(w).includes(id))}
function want(id){return state.explore.includes(id)}
function source(id){const s=D.sources[id];return s?`<a class="source" href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.label)} ↗</a>`:''}
function siteSource(s){return `<a class="source" href="${esc(s.source)}" target="_blank" rel="noopener">Reference ↗ · checked ${esc(s.reviewed)}</a>`}
function stats(){const ws=tasted(),idx=coverageIndex(),dc=distinctCombos(idx);$('#stats').innerHTML=[['Tasting encounters',ws.length],['Atlas places documented',new Set(ws.filter(w=>siteById.has(w.site)).map(w=>w.site)).size+' / '+sites.length],['Combinations tasted',dc.n],...(dc.b?[['Blend combinations',dc.b]]:[]),['Targets tasted',targetProgress(idx)+' / '+state.targets.length],['Comparisons recorded',state.comparisons.length]].map(([l,n])=>`<div class="stat"><strong>${n}</strong><span>${l}</span></div>`).join('')}
function match(...a){return !query||norm(a.flat().join(' ')).includes(norm(query))}
function head(title,desc){return `<div class="view-head"><h2>${title}</h2><p>${desc}</p></div>`}
function options(a,current){return a.map(([v,n])=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(n)}</option>`).join('')}
function selectFilter(id,label,a,current){return `<label>${label}<select id="${id}">${options(a,current)}</select></label>`}
function actions(id,site=false){return `<div class="actions"><button data-action="${site?'site-wine':'topic-wine'}" data-id="${esc(id)}">+ Link a wine</button><button data-action="explore" data-id="${esc(id)}" aria-pressed="${want(id)}">${want(id)?'✓ On my discovery list':'Explore later'}</button></div>`}
const kindRank={'Grand Cru':0,'Area / village':1,'Clos':2,'Lieu-dit':3};
function siteCard(s){
 const n=siteWines(s.id).length,g=siteGeology(s),personal=s.id.startsWith('psite-'),parent=s.parent?siteById.get(s.parent):null;
 const aliases=(s.aliases||[]).filter(a=>norm(a)!==norm(s.name));
 const refs=s.producerRefs||[];
 return `<article class="card"><div class="eyeline">${esc(s.kind)}${personal?' · PERSONAL':''}</div><h4>${esc(s.name)}</h4><div><span class="pill ${n?'seen':''}">${n?`✓ ${n} tasting${n>1?'s':''}`:'Not yet documented'}</span>${want(s.id)?'<span class="pill want">Explore later</span>':''}${g?`<span class="pill">${esc(geoShort(g))}</span>`:''}</div>${s.note?`<p>${esc(s.note)}</p>`:''}<dl class="facts"><dt>Village</dt><dd>${esc(s.village)}</dd>${g||s.soil?`<dt>Geology</dt><dd>${esc(geoName(g))}</dd>`:''}${s.soil&&s.soil!==geoName(g)?`<dt>Source says</dt><dd>${esc(s.soil)}</dd>`:''}${geologyBasis(s)?`<dt>Basis</dt><dd>${esc(geologyBasis(s))}</dd>`:''}${parent?`<dt>Within</dt><dd><button class="linklike" data-action="go-site" data-id="${esc(parent.id)}">${esc(parent.name)}</button></dd>`:''}${aliases.length?`<dt>Also</dt><dd>${esc(aliases.join(' · '))}</dd>`:''}${s.exposure?`<dt>Aspect</dt><dd>${esc(s.exposure)}</dd>`:''}${s.altitude?`<dt>Altitude</dt><dd>${esc(s.altitude)}</dd>`:''}</dl>${refs.length?`<p class="small">Documented producers: ${refs.map(p=>p.url&&safeUrl(p.url)?`<a href="${esc(safeUrl(p.url))}" target="_blank" rel="noopener">${esc(p.name)}</a>`:esc(p.name)).join(' · ')}</p>`:''}${n?`<p>${siteWines(s.id).map(w=>esc(w.producer+' · '+w.cuvee+' '+w.vintage)).join('<br>')}</p>`:''}${s.source&&safeUrl(s.source)?siteSource(s):personal?'<p class="small">Personal entry · no external source recorded</p>':''}${siteProducers(s.id)}<div class="actions"><button data-action="site-wine" data-id="${esc(s.id)}">+ Link a wine</button><button data-action="explore" data-id="${esc(s.id)}" aria-pressed="${want(s.id)}">${want(s.id)?'✓ On my discovery list':'Explore later'}</button>${personal?`<button data-action="edit-site" data-id="${esc(s.id)}">Edit</button><button class="danger" data-action="delete-site" data-id="${esc(s.id)}">Delete</button>`:''}</div></article>`;
}
function atlas(){
 let html=head('The geographical atlas','Follow the region north to south: all 51 Grands Crus, village and area entries, and named lieux-dits and clos. A site is documented only when you link a tasted wine to its verified grape origin.');
 html+=`<div class="filters">${selectFilter('region-filter','Area',[['all','All regions'],...D.regions.map(r=>[r.id,r.name])],region)}${selectFilter('kind-filter','Site type',[['all',`All types (${sites.length})`],...siteKinds.map(k=>[k,`${({'Grand Cru':'Grand Cru','Area / village':'Village / area','Clos':'Clos','Lieu-dit':'Named vineyard / lieu-dit'})[k]} (${sites.filter(s=>s.kind===k).length})`]),['personal',`Personal additions (${state.personalSites.length})`]],kind)}${selectFilter('soil-filter','Geology category',[['all','All settings'],...geoCats.map(c=>[c.id,c.name]),['unknown','Not classified']],soil)}${selectFilter('coverage-filter','Your exploration',[['all','All'],['seen','Wine documented'],['unseen','No wine documented'],['want','Explore later']],coverage)}</div>`;
 html+='<div class="actions"><button data-action="add-site">+ Add a missing vineyard</button></div>';
 html+='<p class="small">Geology categories normalize the sourced wording for filtering; whole-site references simplify parcel variation, and mixed formations stay one explicit mixed setting. Absence from this catalogue never proves a site does not exist — add it above with a source.</p>';
 let count=0;
 for(const r of D.regions){if(region!=='all'&&region!==r.id)continue;const list=sites.filter(s=>s.region===r.id&&(kind==='all'||kind==='personal'&&s.id.startsWith('psite-')||s.kind===kind)&&(soil==='all'||(soil==='unknown'?!siteGeology(s):siteGeology(s)===soil))&&match(s.name,s.aliases||[],s.village,s.soil,geoName(siteGeology(s)),s.note,siteWines(s.id).map(w=>`${w.producer} ${w.cuvee} ${w.notes}`))&&(coverage==='all'||coverage==='seen'&&siteWines(s.id).length||coverage==='unseen'&&!siteWines(s.id).length||coverage==='want'&&want(s.id))).sort((a,b)=>(kindRank[a.kind]??9)-(kindRank[b.kind]??9)||a.name.localeCompare(b.name));if(!list.length)continue;count+=list.length;
 html+=`<section class="region"><div class="eyeline">REGION ${r.number}</div><h3>${esc(r.name)} <span>${list.length} places shown</span></h3><p class="region-desc">${esc(r.description)}</p><div class="grid">${list.map(siteCard).join('')}</div></section>`;
 }
 return html+(count?'':'<div class="empty">No places match these filters. Try another area or clear the search.</div>')+catalogueReport();
}
function catalogueReport(){
 const rows=D.regions.map(r=>{const c=k=>baseSites.filter(s=>s.region===r.id&&s.kind===k).length;return `<tr><th scope="row">${esc(r.name)}</th><td>${c('Grand Cru')}</td><td>${c('Clos')}</td><td>${c('Lieu-dit')}</td><td>${baseSites.filter(s=>s.region===r.id&&s.kind!=='Area / village'&&!siteGeology(s)).length}</td></tr>`}).join('');
 const named=baseSites.filter(s=>s.kind==='Clos'||s.kind==='Lieu-dit'),unclassified=named.filter(s=>!siteGeology(s)).length;
 return `<details class="axis"><summary>Catalogue coverage &amp; known gaps <small>${named.length} clos &amp; lieux-dits beyond the Grands Crus</small></summary><div class="callout"><p>This catalogue holds the 51 Grands Crus, ${D.places.length} village or area entries and ${named.length} verified clos and lieux-dits (reviewed ${esc(L.reviewed)}), each with its source. It is <strong>not</strong> a complete list of Alsace's vineyards: the region has many hundreds of cadastral lieux-dits. ${unclassified} of the ${named.length} named sites have no documented geology and stay unclassified rather than guessed. Add anything missing with “Add a missing vineyard”.</p></div><div class="mx-wrap"><table class="mx report"><thead><tr><th scope="col">Area</th><th scope="col">Grands Crus</th><th scope="col">Clos</th><th scope="col">Lieux-dits</th><th scope="col">Geology unknown</th></tr></thead><tbody>${rows}</tbody></table></div><p class="small">Known gaps:</p><ul class="source-list">${L.knownGaps.map(g=>`<li>${esc(g)}</li>`).join('')}</ul><p class="small">Further reading: ${L.furtherReading.map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.label)}</a>`).join(' · ')}</p></details>`;
}
function openSite(s={}){
 $('#dialog-title').textContent=s.id?'Edit personal vineyard':'Add a missing vineyard';
 $('#editor-body').innerHTML=`<form id="site-form"><p class="small">Search the atlas first to avoid duplicates (check alternative spellings). Record the geographical site, not a producer cuvée name. Leave the geology unknown rather than guessing.</p><div class="form-grid">${field('name','Site name *',s.name)}${field('village','Village(s) *',s.village)}${select('kind','Site type',[['Lieu-dit','Lieu-dit'],['Clos','Clos'],['Area / village','Area / village']],s.kind||'Lieu-dit')}${select('region','Geographical area',D.regions.map(r=>[r.id,r.name]),s.region||D.regions[0].id)}${select('parent','Within another site · optional',[['','Not inside another catalogued site'],...D.regions.flatMap(r=>sites.filter(x=>x.region===r.id&&x.id!==s.id).map(x=>[x.id,`${x.name} · ${x.kind}`]))],s.parent,true)}${select('geology','Geology category · only if sourced',[['','Unknown / not classified'],...geoCats.map(c=>[c.id,c.name])],s.geology)}${field('soil','Original geological description · as your source words it',s.soil,'text',true)}${field('basis','Classification basis · e.g. producer technical sheet',s.basis,'text',true)}${field('source','Source URL',s.source,'url',true)}${area('notes','Notes',s.notes)}</div><div class="form-actions"><button type="button" data-action="close">Cancel</button><button class="primary" type="submit">Save vineyard</button></div></form>`;
 const f=$('#site-form');f.elements.name.required=true;f.elements.village.required=true;$('#dialog-notice').textContent='';$('#editor').showModal();
 f.onsubmit=e=>{e.preventDefault();const d=new FormData(f),n={id:s.id||'psite-'+uid()};for(const k of ['name','village','kind','region','parent','geology','soil','basis','source','notes'])n[k]=String(d.get(k)??'').trim();
  if(sites.some(x=>x.id!==n.id&&norm(x.name)===norm(n.name)&&x.region===n.region&&norm(x.village)===norm(n.village))){notify('This site already exists in the catalogue for that village.');return}
  if(n.geology&&!n.soil.trim()&&!n.source.trim()&&!n.basis.trim()){notify('A geology category needs a description, basis or source; otherwise leave it unknown.');return}
  try{state=validate({...state,personalSites:s.id?state.personalSites.map(x=>x.id===s.id?n:x):[...state.personalSites,n]})}catch(err){notify(err.message);return}
  const saved=save();$('#editor').close();render();if(saved)notify('Vineyard saved. You can now link wines to it.');};
}
function learn(){let html=head('Learning axes','Build several kinds of understanding. A linked tasting records an encounter; comparisons and personal conclusions live in their own view.');
 html+='<div class="callout">One wine can contribute to several topics. Add only methods and origins you can verify; leave unknown details blank. Your observations come before any suggested flavour profile.</div>';
 let count=0;for(const a of D.axes){const ts=D.topics.filter(t=>t.axis===a.id&&match(t.name,t.detail,t.question,topicWines(t.id).map(w=>w.notes)));if(!ts.length)continue;count+=ts.length;html+=`<details class="axis" ${query||a.id==='grapes'?'open':''}><summary>${esc(a.title)} <small>${ts.filter(t=>topicWines(t.id).length).length} / ${ts.length} topics with a wine</small></summary><p class="region-desc">${esc(a.description)}</p><div class="grid">${ts.map(t=>`<article class="card"><h4>${esc(t.name)}</h4><span class="small">${topicWines(t.id).length} linked tasting encounters</span><p>${esc(t.detail)}</p><p class="question">Ask yourself: ${esc(t.question)}</p>${source(t.source)}${actions(t.id)}</article>`).join('')}</div></details>`}return html+(count?'':'<div class="empty">No matching learning topics.</div>')}
function originLinks(){const links=state.producerSites.map(l=>({...l,manual:true}));for(const w of state.wines){if(w.producerId&&w.site&&w.originEvidence&&!links.some(l=>l.producerId===w.producerId&&l.site===w.site))links.push({producerId:w.producerId,site:w.site,relationship:'wine',evidence:w.originEvidence,manual:false});}return links}
function relationLabel(l){return l.relationship==='grower'?'Grows grapes here':l.manual?'Makes wine from here':'Origin recorded in journal'}
function producerOrigins(id){const ls=originLinks().filter(l=>l.producerId===id);return `<details class="origin-links" ${ls.length?'open':''}><summary>Atlas origins · ${ls.length}</summary>${ls.map(l=>`<div class="origin-link"><button data-action="go-site" data-id="${esc(l.site)}">${esc(siteById.get(l.site).name)}</button><p class="small">${relationLabel(l)} · ${esc(l.evidence)}</p>${l.manual?`<button data-action="edit-origin" data-id="${esc(l.producerId)}" data-site="${esc(l.site)}">Edit link</button><button data-action="delete-origin" data-id="${esc(l.producerId)}" data-site="${esc(l.site)}">Remove link</button>`:''}</div>`).join('')||'<p class="small">No origins linked yet. Add a source or record a bottle with a verified origin.</p>'}<button data-action="link-origin" data-id="${esc(id)}">+ Link an atlas place</button></details>`}
function siteProducers(id){const ls=originLinks().filter(l=>l.site===id);return `<details class="origin-links"><summary>Linked producers · ${ls.length}</summary>${ls.map(l=>`<div class="origin-link"><button data-action="go-producer" data-id="${esc(l.producerId)}">${esc(producerById(l.producerId).name)}</button><p class="small">${relationLabel(l)} · ${esc(l.evidence)}</p></div>`).join('')||'<p class="small">Link a producer to this place to build your atlas.</p>'}<button data-action="site-link-producer" data-id="${esc(id)}">+ Link a producer</button></details>`}
function openOrigin(producerId='',site='',edit=false){const old=edit?state.producerSites.find(l=>l.producerId===producerId&&l.site===site):{};$('#dialog-title').textContent=edit?'Edit producer origin':'Link producer & atlas place';$('#editor-body').innerHTML=`<form id="origin-form"><p class="small">A producer can have several origins. A bottle from a site establishes wine origin; select “Grows grapes here” only when a source confirms cultivation. This link does not count as a tasting.</p>${select('producerId','Producer',[['','Choose producer'],...allProducers().slice().sort((a,b)=>a.name.localeCompare(b.name)).map(p=>[p.id,p.name+' · '+p.village])],producerId)}${select('site','Atlas place',[['','Choose place'],...sites.map(s=>[s.id,s.name+' · '+s.kind])],site)}${select('relationship','Relationship',[['wine','Makes wine from here'],['grower','Grows grapes here']],old?.relationship||'wine')}${area('evidence','Source / evidence · producer page, technical sheet or label',old?.evidence)}<div class="form-actions"><button type="button" data-action="close">Cancel</button><button class="primary" type="submit">Save origin link</button></div></form>`;const f=$('#origin-form');f.elements.producerId.required=true;f.elements.site.required=true;f.elements.evidence.required=true;$('#dialog-notice').textContent='';$('#editor').showModal();f.onsubmit=e=>{e.preventDefault();const data=new FormData(f),l=Object.fromEntries([...data].map(([k,v])=>[k,String(v).trim()]));const remaining=state.producerSites.filter(x=>!(edit&&x.producerId===producerId&&x.site===site));if(remaining.some(x=>x.producerId===l.producerId&&x.site===l.site)){notify('This pair already has a link. Edit that link instead.');return}try{state=validate({...state,producerSites:[...remaining,l]})}catch(err){notify(err.message);return}const saved=save();$('#editor').close();render();if(saved)notify('Producer and atlas place linked.');};}

function producerMatch(...values){const text=norm(values.flat().join(' '));return norm(query).split(/\s+/).filter(Boolean).every(word=>text.includes(word))}
function allProducers(){return [...window.ALSACE_PRODUCERS.entries,...state.producers]}
function producerById(id){return allProducers().find(p=>p.id===id)}
function producerWines(id){return state.wines.filter(w=>w.producerId===id)}
function producers(){
 const meta=window.ALSACE_PRODUCERS;
 let html=head('Producers · north to south','Find a grower or cellar, then record its bottles in your wine journal. Locations describe the cellar, not the origin of every wine.');
 html+=`<details class="callout"><summary>Directory coverage · ${meta.entries.length} sourced cellar listings</summary><p>${meta.directoryCount} listings from the <a href="${esc(meta.source)}" target="_blank" rel="noopener">official Alsace Wine Route directory</a>, retrieved ${esc(meta.reviewed)}, cross-checked with <a href="${esc(meta.secondarySource)}" target="_blank" rel="noopener">Synvira’s independent-grower directory</a> (${meta.secondaryAdded} additional listings). Source names and multiple cellar or trading-name listings are retained; the count is not a count of unique companies. This visitor directory includes estates, cooperatives and multiple cellar locations; it is not a census of every wine grower. Add missing producers to your personal directory below. Entries are sorted by latitude within each area; entries without coordinates use the village latitude when available. Personal additions follow alphabetically.</p></details><div class="actions"><button class="primary" data-action="add-producer">+ Add a missing producer</button></div><div class="filters">${selectFilter('producer-region','Area',[['all','All regions'],...D.regions.map(r=>[r.id,r.name])],producerRegion)}${selectFilter('producer-status','Your bottles',[['all','All producers'],['tasted','With tasted wines'],['wishlist','With wishlist bottles'],['want','Explore later'],['personal','Personal additions']],producerStatus)}</div>`;
 let count=0;for(const r of D.regions){if(producerRegion!=='all'&&r.id!==producerRegion)continue;
 const ps=allProducers().filter(p=>p.region===r.id&&producerMatch(p.name,p.aliases||[],p.village,p.notes,producerWines(p.id).map(w=>`${w.cuvee} ${w.notes}`))&&(producerStatus==='all'||producerStatus==='tasted'&&producerWines(p.id).some(w=>w.status==='tasted')||producerStatus==='wishlist'&&producerWines(p.id).some(w=>w.status==='wishlist')||producerStatus==='want'&&want(p.id)||producerStatus==='personal'&&p.id.startsWith('personal-'))).sort((a,b)=>(b.lat||b.sortLat||0)-(a.lat||a.sortLat||0)||a.village.localeCompare(b.village)||a.name.localeCompare(b.name));
 if(!ps.length)continue;count+=ps.length;
 html+=`<section class="region"><div class="eyeline">REGION ${r.number}</div><h3>${esc(r.name)} <span>${ps.length} listings</span></h3><div class="grid">${ps.map(p=>{const ws=producerWines(p.id),t=ws.filter(w=>w.status==='tasted').length;return `<article class="card producer-card" data-producer="${esc(p.id)}"><div class="eyeline">${esc(p.village)}</div><h4>${esc(p.name)}</h4><div><span class="pill ${t?'seen':''}">${t} tasted · ${ws.length-t} wishlist</span>${want(p.id)?'<span class="pill want">Explore later</span>':''}</div>${producerOrigins(p.id)}${p.aliases?.length?`<p class="small">Also listed as: ${esc([...new Set(p.aliases)].filter(n=>norm(n)!==norm(p.name)).join(' · '))}</p>`:''}${p.notes?`<p class="notes">${esc(p.notes)}</p>`:''}${ws.length?`<ul class="producer-bottles">${ws.map(w=>`<li><button data-action="edit-wine" data-id="${esc(w.id)}">${esc(w.cuvee||'Unnamed wine')} ${esc(w.vintage)} · ${w.status==='tasted'?'Tasted':'Wishlist'}</button></li>`).join('')}</ul>`:''}${p.additionalSources?.length?`<a class="source" href="${esc(p.additionalSources[0])}" target="_blank" rel="noopener">Synvira cross-reference ↗</a>`:''}${safeUrl(p.source)?`<a class="source" href="${esc(safeUrl(p.source))}" target="_blank" rel="noopener">${p.sourceKind==='route-directory'?'Wine Route directory':p.sourceKind==='synvira'?'Synvira directory':'Producer reference'} ↗</a>`:'<p class="small">Personal entry · location supplied by you</p>'}<div class="actions"><button data-action="producer-wine" data-id="${esc(p.id)}">+ Record a bottle</button><button data-action="producer-wishlist" data-id="${esc(p.id)}">+ Wishlist bottle</button><button data-action="explore" data-id="${esc(p.id)}" aria-pressed="${want(p.id)}">${want(p.id)?'✓ Explore later':'Explore later'}</button>${p.id.startsWith('personal-')?`<button data-action="edit-producer" data-id="${esc(p.id)}">Edit producer</button><button class="danger" data-action="delete-producer" data-id="${esc(p.id)}">Delete</button>`:''}</div></article>`}).join('')}</div></section>`;
 }return html+(count?'':'<div class="empty">No producers match. Clear the search or add a missing producer.</div>');
}
function openProducer(p={}){
 $('#dialog-title').textContent=p.id?'Edit personal producer':'Add a missing producer';
 $('#editor-body').innerHTML=`<form id="producer-form"><p class="small">Search the directory first to avoid duplicates. You can link existing journal records by editing their producer selection.</p><div class="form-grid">${field('producer','Producer name *',p.name)}${field('village','Cellar town / village *',p.village)}${select('region','Geographical area',D.regions.map(r=>[r.id,r.name]),p.region||D.regions[0].id,true)}${field('source','Producer website / reference',p.source,'url',true)}${area('notes','Personal producer notes',p.notes)}</div><div class="form-actions"><button type="button" data-action="close">Cancel</button><button class="primary" type="submit">Save producer</button></div></form>`;
 $('#producer-form').elements.village.required=true;$('#dialog-notice').textContent='';$('#editor').showModal();
 $('#producer-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),n={id:p.id||'personal-'+uid(),name:String(f.get('producer')).trim(),village:String(f.get('village')).trim(),region:String(f.get('region')),source:String(f.get('source')).trim(),notes:String(f.get('notes')).trim()};if(allProducers().some(x=>x.id!==n.id&&norm(x.name)===norm(n.name)&&norm(x.village)===norm(n.village))){notify('This producer and village already exist. Use the existing entry.');return}try{state=validate({...state,producers:p.id?state.producers.map(x=>x.id===p.id?n:x):[...state.producers,n]})}catch(err){notify(err.message);return}const saved=save();$('#editor').close();render();if(saved)notify('Producer saved. You can now record its bottles.');};
}

function journal(){const ws=state.wines.filter(w=>(wineStatus==='all'||w.status===wineStatus)&&match(Object.values(w),siteById.get(w.site)?.name,wineTopics(w).map(t=>topicById.get(t)?.name))).slice().sort((a,b)=>(b.date||'').localeCompare(a.date||''));return head('Your wine journal','Record a bottle once per tasting encounter and connect it to places and topics. Add a buying lead as a wishlist entry; it will not count as tasted.')+`<div class="filters">${selectFilter('wine-status','Show',[['all','Tastings & wishlist'],['tasted','Tasted'],['wishlist','Wishlist / buying leads']],wineStatus)}</div><p class="count-line">${ws.length} records shown</p>`+(ws.length?`<div class="journal-list">${ws.map(w=>`<article class="card wine-card"><div class="eyeline">${w.status==='tasted'?'TASTED':'WISHLIST'} · ${esc(w.date||'Date not recorded')}</div><h4>${esc(w.producer)}<br>${esc(w.cuvee)} ${esc(w.vintage)}</h4><p>${esc([w.grape,w.designation].filter(Boolean).join(' · '))}</p><dl class="facts"><dt>Cellar</dt><dd>${esc(w.cellar||'Not recorded')}</dd><dt>Grapes</dt><dd>${esc(w.multiOrigin?'Several origins':siteById.get(w.site)?.name||(w.originRegion?areaName(w.originRegion)+' · vineyard unknown':'')||w.origin||'Origin not confirmed')}${w.grape==='Blend / other'&&(w.blendGrapes?.length||w.blendNote)?' · blend: '+esc([...(w.blendGrapes||[]),w.blendNote].filter(Boolean).join(' · ')):''}${!wineArea(w)&&!w.multiOrigin&&w.status==='tasted'?'<br><button class="linklike" data-action="complete-origin" data-id="'+esc(w.id)+'">Complete origin</button>':''}</dd>${w.originEvidence?`<dt>Evidence</dt><dd>${esc(w.originEvidence)}</dd>`:''}</dl><div>${wineTopics(w).map(t=>`<span class="pill">${esc(topicById.get(t)?.name||t)}</span>`).join('')}</div>${w.notes?`<p class="notes">${esc(w.notes)}</p>`:''}${w.seller||w.price||w.availability?`<p>Buying lead: ${esc([w.seller,w.country,w.price,w.availability].filter(Boolean).join(' · '))}<br><span class="small">Last checked: ${esc(w.checkedDate||'Not verified')}. Stock can change.</span></p>`:''}${safeUrl(w.url)?`<a class="source" href="${esc(safeUrl(w.url))}" target="_blank" rel="noopener">Seller / technical sheet ↗</a>`:''}<div class="actions"><button data-action="edit-wine" data-id="${esc(w.id)}">Edit</button><button data-action="repeat-wine" data-id="${esc(w.id)}">Taste again</button><button class="danger" data-action="delete-wine" data-id="${esc(w.id)}">Delete</button></div></article>`).join('')}</div>`:'<div class="empty">No wines here yet. Record a tasting, or save a bottle you would like to find. Older checklist marks are preserved under Backup & history.</div>')}
function compare(){return head('Comparisons that teach','Choose two or more tasted journal records, then write what you noticed. The same bottle tasted on different occasions can have separate records. There is no prescribed “correct” flavour.')+`<div class="grid">${D.comparisons.filter(e=>match(e.name,e.question,state.comparisons.filter(c=>c.exercise===e.id).map(c=>c.notes))).map(e=>`<article class="card"><h4>${esc(e.name)}</h4><p>${esc(e.question)}</p><span class="small">${state.comparisons.filter(c=>c.exercise===e.id).length} recorded comparisons</span><div class="actions"><button data-action="new-comparison" data-id="${e.id}">+ Record comparison</button></div></article>`).join('')}</div><section class="region"><h3>Your observations</h3>${state.comparisons.length?state.comparisons.filter(c=>match(c.notes,D.comparisons.find(e=>e.id===c.exercise)?.name)).map(c=>`<article class="card"><h4>${esc(D.comparisons.find(e=>e.id===c.exercise)?.name)}</h4><p>${esc(c.date)}</p><p>${c.wines.map(id=>{const w=state.wines.find(x=>x.id===id);return esc(w?`${w.producer} ${w.cuvee} ${w.vintage}`:'Missing record')}).join(' ↔ ')}</p><p class="notes">${esc(c.notes)}</p><div class="actions"><button data-action="edit-comparison" data-id="${esc(c.id)}">Edit</button><button data-action="delete-comparison" data-id="${esc(c.id)}">Delete</button></div></article>`).join(''):'<p class="small">Your first comparison starts with two tasted records in the journal.</p>'}</section>`}
function backup(){const ids=[...new Set([...Object.keys(state.legacy.checked),...Object.keys(state.legacy.notes)])];return head('Keep your discoveries','Your journal stays in this browser. Export a backup to move it between devices or protect it before clearing browser data.')+`<div class="actions"><button class="primary" data-action="export">Export complete backup</button><button data-action="copy">Copy readable journal</button></div><label class="inline-file">Import a JSON backup (new atlas or old checklist)<input id="import-file" type="file" accept="application/json,.json"></label><p class="small">An atlas backup replaces the current atlas after confirmation. A legacy backup merges into the preserved history; it does not create fictional bottles or completed comparisons.</p><details class="axis" ${ids.length?'open':''}><summary>Preserved checklist history <small>${Object.keys(state.legacy.checked).length} old marks · ${Object.keys(state.legacy.notes).length} notes</small></summary><p class="small">Historical labels are shown as originally saved, not as updated reference facts. Existing marks and notes remain intact. To link an old tasting to the atlas, record its bottle details in the journal.</p>${ids.filter(id=>match(D.legacy[id]?.name,state.legacy.notes[id],id)).map(id=>`<div class="legacy-row"><strong>${state.legacy.checked[id]?'✓ ':''}${esc(D.legacy[id]?.name||id)}</strong><span class="small"> · ${esc(D.legacy[id]?.section||'Imported item')}</span>${state.legacy.notes[id]?`<p>${esc(state.legacy.notes[id])}</p>`:''}<button data-action="legacy-wine" data-id="${esc(id)}">Use note in a wine record</button></div>`).join('')||'<p>No previous checklist data found in this browser. You can import an old JSON backup.</p>'}</details><details class="axis"><summary>Sources & reading</summary><p>Site metadata was checked against CIVA pages on 12 September 2026. Whole-site descriptions simplify parcel variation. Learning questions are editorial, and buying availability is user-recorded rather than a stock promise.</p><ul class="source-list">${Object.values(D.sources).map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.label)}</a></li>`).join('')}</ul></details>`}
// --- Coverage matrix -------------------------------------------------------
function coverageIndex(){
 const map=new Map(),add=(key,w,slot)=>{let c=map.get(key);if(!c){c={tasted:[],wishlist:[],blend:[]};map.set(key,c)}c[slot].push(w)};
 for(const w of state.wines){
  const g=wineGrapeKey(w),geo=wineGeo(w),area=wineArea(w);
  if(g)add(comboKey(g,geo,area),w,w.status==='tasted'?'tasted':'wishlist');
  if(w.status==='tasted')for(const bg of (w.blendGrapes||[]))add(comboKey(bg,geo,area),w,'blend');
 }
 return map;
}
const areaName=id=>id==='all'||id==='any'?'All areas':id===''?'Area unknown':(id.startsWith('site:')?siteById.get(id.slice(5))?.name||id:D.regions.find(r=>r.id===id)?.name||id);
function cellData(idx,g,geo,area){
 const out={tasted:[],wishlist:[],blend:[],areas:[]};
 if(area.startsWith('site:')){
  for(const w of state.wines){if(w.multiOrigin||w.site!==area.slice(5)||wineGeo(w)!==geo)continue;
   if(wineGrapeKey(w)===g)out[w.status==='tasted'?'tasted':'wishlist'].push(w);
   if(w.status==='tasted'&&(w.blendGrapes||[]).includes(g))out.blend.push(w);
  }return out;
 }

 for(const a of (area==='all'?D.regions.map(r=>r.id):[area])){const c=idx.get(comboKey(g,geo,a));if(!c)continue;out.tasted.push(...c.tasted);out.wishlist.push(...c.wishlist);out.blend.push(...c.blend);if(c.tasted.length)out.areas.push(a)}
 return out;
}
const targetKey=(g,geo,area)=>comboKey(g,geo,area==='all'?'any':area);
const isTarget=(g,geo,area)=>state.targets.includes(targetKey(g,geo,area));
function naFor(g,geo,area){
 const manual=state.excluded.find(e=>e.key===targetKey(g,geo,area));if(manual)return manual;
 const site=area.startsWith('site:')?siteById.get(area.slice(5)):null;
 const known=siteGeology(site);
 // Reference mismatch, never a claim that a grape cannot grow on a rock.
 if(site&&geo&&known&&known!==geo&&!cellData(null,g,geo,area).tasted.length&&!cellData(null,g,geo,area).wishlist.length)
  return {automatic:true,reason:`Outside this site's reference classification (${geoName(known)}). A documented parcel may differ.`,source:site.source};
}

function distinctCombos(idx){let n=0,b=0;for(const [k,c] of idx){if(!c.tasted.length)continue;const [g,geo,area]=k.split('|');if(!geo||!area)continue;if(g==='blend')b++;else n++}return {n,b}}
function targetProgress(idx){let done=0;for(const k of state.targets){const [g,geo,a]=k.split('|');if(cellData(idx,g,geo,a==='any'?'all':a).tasted.length)done++}return done}
function matrixCell(idx,g,geo,area){
 const c=cellData(idx,g,geo,area),na=naFor(g,geo,area),target=isTarget(g,geo,area);
 let cls='mx-empty',mark='·',sub='',label='unknown: no matching example documented';
 const documented=sites.some(s=>(area==='all'||s.region===area||area==='site:'+s.id)&&siteGeology(s)===geo&&(s.documentedGrapes||[]).includes(g));
 if(documented){cls='mx-doc';mark='○';label='documented by a producer; not yet tasted'}
 if(na){cls='mx-na';mark='×';label=(na.automatic?'reference mismatch: ':'marked not applicable: ')+na.reason}
 if(c.wishlist.length&&!na){cls='mx-doc';mark='○';sub=String(c.wishlist.length);label=`not yet tasted: ${c.wishlist.length} documented wishlist wine${c.wishlist.length>1?'s':''}`}
 if(target&&!c.tasted.length){cls+=' mx-target';label+='; marked as a target'}
 if(c.tasted.length){cls='mx-tasted'+(target?' mx-target':'');mark='✓';sub=String(c.tasted.length);label=`tasted: ${c.tasted.length} encounter${c.tasted.length>1?'s':''}`+(area==='all'?` across ${c.areas.length} area(s)`:'')+(target?'; target reached':'')}
 const blendHint=g!=='blend'&&!c.tasted.length&&c.blend.length?`<span class="mx-blend" title="Blend encounters only – not single-variety coverage">b</span>`:'';
 const areaHint=area==='all'&&c.tasted.length?`<span class="mx-sub">${c.areas.length} area${c.areas.length===1?'':'s'}</span>`:'';
 return `<td><button class="mx-cell ${cls}" data-action="mx-cell" data-g="${esc(g)}" data-geo="${esc(geo)}" data-area="${esc(area)}" aria-label="${esc(`${grapeLabel(g)}, ${geoName(geo)}, ${areaName(area)}: ${label}`)}"><span class="mx-mark">${mark}${sub?`<span class="mx-count">${sub}</span>`:''}${target?'<span class="mx-flag" aria-hidden="true">◆</span>':''}${blendHint}</span>${areaHint}</button></td>`;
}
function matrix(){
 const idx=coverageIndex(),dc=distinctCombos(idx),cols=[...geoCats.map(c=>c.id),''];
 let html=head('Coverage matrix','Grape variety × geological setting × geographical area. Every checkmark is backed by a tasted journal record whose origin supports the cell; wishlist bottles never count as tasted.');
 html+=`<div class="filters">${selectFilter('mx-mode','View',[['grape-geo','Grapes × geology'],['area-geo','One grape · areas × geology'],['site-geo','One grape · atlas sites × geology']],mxMode)}${mxMode==='grape-geo'?selectFilter('mx-area','Geographical area',[['all','All areas · overview'],...D.regions.map(r=>[r.id,r.name]),...sites.map(s=>['site:'+s.id,s.name+' · '+s.village+' · '+s.kind])],mxArea):selectFilter('mx-grape','Grape',[...singleGrapes.map(g=>[g,g]),['blend','Blend / field blend']],mxGrape)}</div>`;
 if(mxMode==='site-geo')html+=selectFilter('mx-site-area','Filter atlas sites by area',[['all','All areas'],...D.regions.map(r=>[r.id,r.name])],mxSiteArea);
 html+=`<p class="count-line">${dc.n} distinct grape × geology × area combination${dc.n===1?'':'s'} tasted${dc.b?` · ${dc.b} blend combination${dc.b===1?'':'s'}`:''} · targets tasted ${targetProgress(idx)} / ${state.targets.length}. Only fully classified records count as exact combinations; there is deliberately no “percentage of Alsace”.</p>`;
 html+=`<div class="mx-legend small"><span><b class="mx-tasted">✓</b> Tasted (encounters)</span><span><b>◆</b> Target</span><span><b class="mx-doc">○</b> Documented producer example or wishlist wine</span><span><b>·</b> Unknown · nothing documented</span><span><b>×</b> Outside site classification / excluded · tap for reason</span><span><b class="mx-blend-demo">b</b> Blend encounters only</span></div>`;
 const rows=mxMode==='grape-geo'?[...singleGrapes,'blend']:mxMode==='site-geo'?sites.filter(s=>(mxSiteArea==='all'||s.region===mxSiteArea)&&match(s.name,s.village,s.kind,s.aliases||[])).map(s=>'site:'+s.id):D.regions.map(r=>r.id);
 const rowHead=r=>mxMode==='grape-geo'?grapeLabel(r):r.startsWith('site:')?`${areaName(r)} · ${siteById.get(r.slice(5)).village}`:areaName(r);
 const cell=(r,geo)=>mxMode==='grape-geo'?matrixCell(idx,r,geo,mxArea):matrixCell(idx,mxGrape,geo,r);
 html+=`<p class="small mx-caption"><strong>${mxMode==='grape-geo'?esc(areaName(mxArea)):esc(grapeLabel(mxGrape))}</strong> · rows are ${mxMode==='grape-geo'?'grape varieties':mxMode==='site-geo'?'atlas sites':'geographical areas'}, columns are geology categories. Tap or press Enter on a cell for its wines and actions.<span class="mx-hint"> Swipe the table sideways to see every geology column.</span></p><div class="mx-wrap" tabindex="0" role="group" aria-label="Coverage matrix table, scrollable"><table class="mx"><thead><tr><th scope="col">${mxMode==='grape-geo'?'Grape':mxMode==='site-geo'?'Atlas site':'Area'}</th>${cols.map(c=>`<th scope="col"><span class="mx-colname">${esc(geoShort(c))}</span></th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${esc(rowHead(r))}</th>${cols.map(cId=>cell(r,cId)).join('')}</tr>`).join('')}</tbody></table></div>`;
 const unplaced=tasted().filter(w=>!wineGrapeKey(w)||!wineArea(w)).length;
 if(unplaced)html+=`<p class="small">${unplaced} tasted record${unplaced===1?' is':'s are'} not placed in any cell because the grape, the area or a single origin is unknown. <button class="linklike" data-action="go-journal-incomplete">Review in the journal</button></p>`;
 html+=`<details class="axis"><summary>How coverage is classified</summary><div class="callout"><p><strong>Tasted ✓</strong> needs at least one tasted journal record whose grape, geology and area all support the cell. <strong>Not yet tasted ○</strong> means a matching wine is documented in your wishlist. <strong>Unknown ·</strong> means nothing matching is documented — absence from the catalogue is not proof a combination does not exist. <strong>×</strong> flags a documented site's different geology or your own exclusion. It is not a biological or appellation restriction on the grape. Missing grape evidence stays unknown. Parcel-level evidence can override the reference. Site rows count exact recorded origins, not every parent or neighbouring vineyard.</p><p><strong>Geography</strong> follows the verified origin of the grapes, never the cellar address. A record with a known area but unknown vineyard counts toward that area under “Unknown geology” without inventing a geological class. <strong>Geology</strong> comes from the linked site's normalized category (whole-vineyard reference scale, original wording preserved); a sourced parcel-level correction on the wine record overrides it. Documented mixed formations are one explicit mixed setting — never double-counted as two pure examples.</p><p><strong>Blends</strong> live in their own row: a blend containing Riesling never marks the single-variety Riesling cell (a small “b” hints that only blend encounters exist there). Repeat tastings raise the encounter count, not the number of distinct combinations. Editing or deleting a journal record recalculates everything on this page automatically.</p></div></details>`;
 return html;
}
function openCell(g,geo,area){
 const idx=coverageIndex(),c=cellData(idx,g,geo,area),na=naFor(g,geo,area),target=isTarget(g,geo,area);
 $('#dialog-title').textContent=`${grapeLabel(g)} · ${geoName(geo)}`;
 const wineLine=w=>`<li><button data-action="edit-wine" data-id="${esc(w.id)}">${esc(w.producer)} · ${esc(w.cuvee||'Unnamed wine')} ${esc(w.vintage)} · ${esc(w.date||'')}${siteById.get(w.site)?` · ${esc(siteById.get(w.site).name)}`:w.originRegion?` · ${esc(areaName(w.originRegion))}`:''}</button></li>`;
 const catalog=sites.filter(s=>siteGeology(s)===geo&&geo&&(area==='all'||s.region===area||area==='site:'+s.id)).slice(0,14);
 $('#editor-body').innerHTML=`<p class="small">${esc(areaName(area))}${area==='all'?' · a tasting in one area never implies coverage in another; distinct combinations are counted per area':''}</p>
 ${na?`<div class="callout">${esc(na.reason)}${na.source&&safeUrl(na.source)?` <a href="${esc(na.source)}" target="_blank" rel="noopener">Reference ↗</a>`:''}</div>`:''}
 ${geo===''?'<p class="small">“Unknown geology” collects records whose area is known but whose exact site or geology is not. They contribute to geographical coverage without inventing a geological classification.</p>':''}
 <h3 class="mx-h">Tasted encounters · ${c.tasted.length}</h3>${c.tasted.length?`<ul class="mx-list">${c.tasted.map(wineLine).join('')}</ul>`:'<p class="small">No tasted record supports this combination yet. A checkmark only ever comes from a journal record.</p>'}
 ${area==='all'&&c.tasted.length?`<p class="small">Contributing areas: ${[...new Set(c.tasted.map(w=>wineArea(w)))].map(a=>`<span class="pill ${a?'seen':''}">${esc(areaName(a))}</span>`).join(' ')}</p>`:''}
 ${catalog.some(s=>(s.documentedGrapes||[]).includes(g))?`<h3 class="mx-h">Producer-documented examples</h3><ul>${catalog.filter(s=>(s.documentedGrapes||[]).includes(g)).map(s=>`<li><a href="${esc(s.source)}" target="_blank" rel="noopener">${esc(s.name)} · ${esc(g)}</a></li>`).join('')}</ul>`:''}
 <h3 class="mx-h">Wishlist wines · ${c.wishlist.length}</h3>${c.wishlist.length?`<ul class="mx-list">${c.wishlist.map(wineLine).join('')}</ul>`:'<p class="small">No documented wishlist wine matches this exact combination.</p>'}
 ${g!=='blend'&&c.blend.length?`<h3 class="mx-h">Blend encounters containing ${esc(g)} · ${c.blend.length}</h3><p class="small">Shown separately — a blend never counts as single-variety coverage.</p><ul class="mx-list">${c.blend.map(wineLine).join('')}</ul>`:''}
 ${catalog.length?`<h3 class="mx-h">Catalogued sites with this geology${area==='all'?'':' in this area'}</h3><p class="small">These sites match the geology; this does not establish that the selected grape is grown there.</p><p class="small">${catalog.map(s=>`<button class="linklike" data-action="go-site" data-id="${esc(s.id)}">${esc(s.name)}</button>`).join(' · ')}</p>`:''}
 <div class="form-actions mx-actions"><button ${na?.automatic?'disabled':''} data-action="mx-na" data-g="${esc(g)}" data-geo="${esc(geo)}" data-area="${esc(area)}">${na?.automatic?'Reference mismatch':na?'Remove “not applicable”':'Mark not applicable…'}</button><button ${na&&!target?'disabled':''} data-action="mx-target" data-g="${esc(g)}" data-geo="${esc(geo)}" data-area="${esc(area)}" aria-pressed="${target}">${target?'✓ Remove target':'◆ Mark as target'}</button><button class="primary" data-action="mx-record" data-g="${esc(g)}" data-area="${esc(area)}">+ Record a tasting</button></div>
 <p class="small">Recording opens the full journal form: pick the actual site (geology follows the site) or the area if the exact vineyard is unknown. Saving an empty checkmark is deliberately impossible.</p>`;
 $('#dialog-notice').textContent='';$('#editor').showModal();
}
function render(){rebuildSites();stats();$('#view').innerHTML=({atlas,matrix,producers,learn,journal,compare,backup}[tab])();document.querySelectorAll('nav button').forEach(b=>{if(b.dataset.tab===tab)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')})}
function field(name,label,value='',type='text',full=false){return `<label class="${full?'full':''}">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${name==='producer'?'required':''} ${type==='number'?'min="0" step="any"':''}></label>`}
function select(name,label,values,value='',full=false){return `<label class="${full?'full':''}">${label}<select name="${name}">${options(values,value)}</select></label>`}
function area(name,label,v=''){return `<label class="full">${label}<textarea name="${name}">${esc(v)}</textarea></label>`}
function originSuggestions(producerId){
 if(!producerId)return [];
 const out=[],seen=new Set();
 for(const l of originLinks().filter(l=>l.producerId===producerId&&siteById.has(l.site))){if(!seen.has(l.site)){seen.add(l.site);out.push({site:l.site,why:l.manual?'linked in Producers':'from an earlier journal record'})}}
 for(const w of state.wines.filter(w=>w.producerId===producerId&&w.site&&siteById.has(w.site))){if(!seen.has(w.site)){seen.add(w.site);out.push({site:w.site,why:'used in an earlier bottle'})}}
 return out.slice(0,6);
}
function openWine(w={},isNew=false,quick=false){
 $('#dialog-title').textContent=quick?'Quick entry · save now, complete origin later':w.id&&!isNew?'Edit wine record':'Record a wine';
 const id=w.id&&!isNew?w.id:'';
 const lastVenue=[...state.wines].reverse().find(x=>x.venue)?.venue||'';
 const multi=!!w.multiOrigin,more=quick?'':'open';
 const originBlock=`<fieldset class="origin-set"><legend>Where the grapes grew</legend><p class="small">Use the vineyard of the grapes, not the winery address or where you tasted. If you only know the area, choose that and leave the vineyard unknown: it counts toward geography without inventing a geology. You can complete this later from the journal.</p><div class="form-grid">${select('site','Verified vineyard · atlas entry',[['','Unknown / not yet recorded'],...D.regions.flatMap(r=>sites.filter(s=>s.region===r.id).map(s=>[s.id,`${s.name} · ${s.kind}${s.id.startsWith('psite-')?' · personal':''}`]))],w.site,true)}${select('originRegion','Area when the vineyard is unknown',[['','Not recorded'],...D.regions.map(r=>[r.id,r.name])],w.originRegion,true)}<label class="full check"><input type="checkbox" name="multiOrigin" value="1" ${multi?'checked':''}>Grapes from several vineyards or areas: do not count this bottle toward any single site, area or geology</label>${field('originEvidence','Origin evidence · label, producer or technical sheet (required with a vineyard)',w.originEvidence,'text',true)}<div id="origin-suggest" class="full"></div></div></fieldset>`;
 $('#editor-body').innerHTML=`<form id="wine-form" data-id="${esc(id)}" data-quick="${quick?1:''}"><div class="form-grid">${select('status','Record type',[['tasted','Tasted'],['wishlist','Wishlist / buying lead']],w.status||'tasted')}${field('date','Tasting date (or wishlist date)',w.date||today(),'date')}${select('producerId','Link to producer directory',[['','Unlinked / producer not in directory'],...allProducers().slice().sort((a,b)=>a.name.localeCompare(b.name)).map(p=>[p.id,p.name+' · '+p.village])],w.producerId,true)}${field('producer','Producer as recorded on bottle *',w.producer)}${field('cuvee','Wine / cuvée',w.cuvee)}${field('vintage','Vintage / NV',w.vintage)}${select('grape','Grape (confirmed composition)',[['','Unknown / not recorded'],...grapes.map(g=>[g,g==='Blend / other'?'Blend / other (choose components below)':g])],w.grape)}${field('venue','Where you tasted it',w.venue||(isNew||!id?lastVenue:''))}</div><fieldset id="blend-set"><legend>Blend composition · optional</legend><p class="small">A blend never counts as single-variety coverage. Tick components you know; percentages are optional.</p><div class="checks">${singleGrapes.map(g=>`<label class="check"><input type="checkbox" name="blendGrapes" value="${esc(g)}" ${(w.blendGrapes||[]).includes(g)?'checked':''}>${esc(g)}</label>`).join('')}</div><div class="form-grid">${field('blendNote','Composition detail · e.g. “Riesling 60%, Pinot Gris 40%” or “complantation, unknown”',w.blendNote,'text',true)}</div></fieldset>${originBlock}<details class="more" ${more}><summary>More details · label, method, notes, learning topics, buying lead</summary><div class="form-grid">${field('designation','Designation as printed on label',w.designation)}${field('cellar','Producer / cellar location',w.cellar)}${field('origin','Other / multiple grape origins · free text',w.origin,'text',true)}${field('bottleRef','Personal bottle reference (optional)',w.bottleRef)}${field('sugar','Residual sugar g/L · if known',w.sugar,'number')}${field('alcohol','Alcohol % · if known',w.alcohol,'number')}${field('vessel','Fermentation / ageing details · if known',w.vessel,'text',true)}${area('notes','Your observations, enjoyment & questions',w.notes)}</div><fieldset><legend>Parcel-level geology correction · optional</legend><p class="small">The vineyard's category describes the whole site. Use this only if a source documents this bottle's parcel differently.</p><div class="form-grid">${select('parcelGeology','Parcel geology category',[['','Use the vineyard reference'],...geoCats.map(c=>[c.id,c.name])],w.parcelGeology)}${field('parcelGeologyEvidence','Source for the correction',w.parcelGeologyEvidence)}</div></fieldset><fieldset><legend>Additional learning topics</legend><p class="small">The selected grape links automatically to its basic topic. Select other topics only when supported by this wine; methods are not inferred from flavour.</p><div class="checks">${D.topics.map(t=>`<label class="check"><input type="checkbox" name="topics" value="${t.id}" ${(w.topics||[]).includes(t.id)?'checked':''}>${esc(t.name)}</label>`).join('')}</div></fieldset><div class="form-grid">${field('seller','Seller / importer',w.seller)}${field('country','Country',w.country)}${field('price','Price & currency',w.price)}${field('checkedDate','Availability checked on',w.checkedDate,'date')}${select('availability','Availability',[['','Not verified'],['In stock when checked','In stock when checked'],['Previously available','Previously available'],['Out of stock when checked','Out of stock when checked'],['Ask seller','Ask seller']],w.availability)}${field('url','Seller / technical sheet URL',w.url,'url')}</div></details><div class="form-actions"><button type="button" data-action="close">Cancel</button><button class="primary" type="submit">${quick?'Save now':'Save wine record'}</button></div></form>`;$('#dialog-notice').textContent='';$('#editor').showModal();
 const form=$('#wine-form'),el=form.elements;
 const syncBlend=()=>{$('#blend-set').classList.toggle('hidden',el.grape.value!=='Blend / other')};
 const suggest=()=>{const box=$('#origin-suggest'),sg=originSuggestions(el.producerId.value).filter(x=>x.site!==el.site.value);box.innerHTML=sg.length?`<p class="small">Suggested, not confirmed. Choose one only if this bottle really comes from it, then add your evidence:</p><div class="actions">${sg.map(x=>`<button type="button" data-suggest="${esc(x.site)}">${esc(siteById.get(x.site).name)} <span class="small">· ${esc(x.why)}</span></button>`).join('')}</div>`:''};
 syncBlend();suggest();
 el.grape.onchange=syncBlend;
 el.producerId.onchange=e=>{const p=producerById(e.target.value);if(p){el.producer.value=p.name;el.cellar.value=p.village}suggest()};
 $('#origin-suggest').onclick=e=>{const b=e.target.closest('[data-suggest]');if(!b)return;el.site.value=b.dataset.suggest;el.multiOrigin.checked=false;el.originEvidence.placeholder='Confirm how you know this bottle comes from '+siteById.get(b.dataset.suggest).name;el.originEvidence.focus();suggest()};
 form.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),wine={id:id||uid()};for(const [k,v] of f.entries())if(k!=='topics'&&k!=='blendGrapes')wine[k]=String(v).trim();wine.multiOrigin=wine.multiOrigin||'';wine.topics=f.getAll('topics');wine.blendGrapes=wine.grape==='Blend / other'?f.getAll('blendGrapes'):[];if(wine.grape!=='Blend / other')wine.blendNote='';
  if(wine.multiOrigin){wine.site='';wine.originRegion='';wine.parcelGeology='';wine.parcelGeologyEvidence=''}
  if(wine.site&&!wine.originEvidence){notify('Add how you verified the grape origin, or leave the vineyard unknown (you can pick just the area).');el.originEvidence.focus();return}
  if(wine.parcelGeology&&!wine.parcelGeologyEvidence){notify('A parcel-level geology correction needs a source.');el.parcelGeologyEvidence.focus();return}
  if(wine.site){wine.region=siteById.get(wine.site).region;wine.originRegion=''}
  if(id&&wine.status!=='tasted'&&state.comparisons.some(c=>c.wines.includes(id))){notify('This tasting belongs to a comparison. Remove that link before changing it to a wishlist entry.');return}
  const next={...state,wines:id?state.wines.map(w=>w.id===id?wine:w):[...state.wines,wine]};try{state=validate(next)}catch(err){notify(err.message);return}const saved=save();$('#editor').close();render();if(saved)notify(quick&&!wine.site&&!wine.originRegion?'Saved. Complete the origin later from the journal to add it to the matrix.':'Wine saved. Coverage is updated.');});
}
function openComparison(exercise,id=''){const old=state.comparisons.find(c=>c.id===id)||{},e=D.comparisons.find(x=>x.id===exercise);$('#dialog-title').textContent=e.name;$('#editor-body').innerHTML=`<p>${esc(e.question)}</p><form id="comparison-form">${field('date','Date',old.date||today(),'date')}<fieldset><legend>Select at least two tasted records</legend><div class="checks">${tasted().map(w=>`<label class="check"><input type="checkbox" name="wines" value="${esc(w.id)}" ${(old.wines||[]).includes(w.id)?'checked':''}>${esc(w.producer+' · '+w.cuvee+' '+w.vintage+' · '+w.date)}</label>`).join('')||'<p>Add tasted wines to the journal first.</p>'}</div></fieldset>${area('notes','Your observations · what differed, what stayed similar, and possible confounders',old.notes)}<div class="form-actions"><button type="button" data-action="close">Cancel</button><button type="submit" class="primary">Save comparison</button></div></form>`;$('#dialog-notice').textContent='';$('#editor').showModal();$('#comparison-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target),wines=f.getAll('wines');if(wines.length<2){notify('Choose at least two tasted journal records.');return}const notes=String(f.get('notes')).trim();if(!notes){notify('Add an observation before completing this comparison.');return}const c={id:id||uid(),exercise,date:String(f.get('date')),notes,wines};state.comparisons=id?state.comparisons.map(x=>x.id===id?c:x):[...state.comparisons,c];const saved=save();$('#editor').close();render();if(saved)notify('Comparison saved.');}}
function download(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=`alsace-atlas-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function readable(){const history=[...new Set([...Object.keys(state.legacy.checked),...Object.keys(state.legacy.notes)])].map(id=>`${state.legacy.checked[id]?'✓ ':''}${D.legacy[id]?.name||id}\n${state.legacy.notes[id]||''}`);return ['ALSACE WINE JOURNAL',...state.wines.map(w=>`\n${w.status.toUpperCase()} · ${w.producer} — ${w.cuvee} ${w.vintage}\nDate: ${w.date}\nGrape origin: ${w.multiOrigin?'Several origins':siteById.get(w.site)?.name||(w.originRegion?areaName(w.originRegion):'')||w.origin||'Unknown'}\n${w.notes||''}`),'\nPERSONAL VINEYARDS',...state.personalSites.map(x=>`${x.name} · ${x.village} · ${geoName(x.geology)}\n${x.soil||''} ${x.source||''}`),'\nMATRIX TARGETS',...state.targets.map(k=>{const [g,geo,a]=k.split('|');return `${grapeLabel(g)} · ${geoName(geo)} · ${areaName(a)}`}),'\nPRODUCER ORIGINS',...state.producerSites.map(l=>`${producerById(l.producerId).name} · ${siteById.get(l.site).name}\n${relationLabel(l)}: ${l.evidence}`),'\nPERSONAL PRODUCERS',...state.producers.map(p=>`${p.name} · ${p.village}\n${p.notes||''}\n${p.source||''}`),'\nCOMPARISONS',...state.comparisons.map(c=>`${D.comparisons.find(e=>e.id===c.exercise)?.name}\n${c.notes}`),'\nPRESERVED HISTORY',...history].join('\n')}
async function importFile(file){if(!file)return;if(file.size>10*1024*1024){notify('Backup is too large (maximum 10 MB).');return}try{const raw=JSON.parse(await file.text());let next;if(raw.version===3||raw.version===4){next=validate(raw);if(!confirm('Replace this browser’s atlas with this backup? Export your current atlas first if you want to keep both.'))return}else if(raw.checked||raw.notes){const l=legacyValid(raw);next={...state,legacy:{checked:{...state.legacy.checked,...l.checked},notes:{...state.legacy.notes,...l.notes}}};if(!confirm('Merge these old checklist marks and notes into preserved history?'))return}else throw Error('Not an atlas or checklist backup');state=next;const saved=save();render();if(saved)notify('Backup imported successfully.')}catch(e){notify('Import rejected: '+e.message)}}
$('#search').oninput=e=>{query=e.target.value;render()};$('#add-wine').onclick=()=>openWine();$('#quick-wine').onclick=()=>openWine({},true,true);$('#close-dialog').onclick=()=>$('#editor').close();
document.addEventListener('change',e=>{const v=e.target.value;switch(e.target.id){case 'producer-region':producerRegion=v;break;case 'producer-status':producerStatus=v;break;case 'region-filter':region=v;break;case 'kind-filter':kind=v;break;case 'soil-filter':soil=v;break;case 'coverage-filter':coverage=v;break;case 'wine-status':wineStatus=v;break;case 'mx-mode':mxMode=v;break;case 'mx-site-area':mxSiteArea=v;break;case 'mx-area':mxArea=v;break;case 'mx-grape':mxGrape=v;break;case 'import-file':importFile(e.target.files[0]);return;default:return}render()});
document.addEventListener('click',async e=>{
 const nav=e.target.closest('[data-tab]');if(nav){tab=nav.dataset.tab;query='';$('#search').value='';render();return}
 const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id;
 switch(b.dataset.action){
 case 'link-origin':openOrigin(id);break;
 case 'site-link-producer':openOrigin('',id);break;
 case 'edit-origin':openOrigin(id,b.dataset.site,true);break;
 case 'delete-origin':if(confirm('Remove this producer-origin link? Any origin recorded in a bottle will still appear.')){state.producerSites=state.producerSites.filter(l=>!(l.producerId===id&&l.site===b.dataset.site));save();render()}break;
 case 'go-site':if($('#editor').open)$('#editor').close();tab='atlas';region=kind=soil=coverage='all';query=siteById.get(id).name;$('#search').value=query;render();$('#view').scrollIntoView();break;
 case 'go-producer':tab='producers';producerRegion=producerStatus='all';query=producerById(id).name;$('#search').value=query;render();$('#view').scrollIntoView();break;
 case 'add-producer':openProducer();break;
 case 'edit-producer':openProducer(producerById(id));break;
 case 'delete-producer':if(producerWines(id).length){notify('This producer has linked bottles. Unlink them in the journal before deleting the producer.');break}if(confirm('Delete this personal producer?')){state.producerSites=state.producerSites.filter(l=>l.producerId!==id);state.producers=state.producers.filter(p=>p.id!==id);state.explore=state.explore.filter(x=>x!==id);save();render()}break;
 case 'producer-wine':case 'producer-wishlist':{const p=producerById(id);openWine({producerId:p.id,producer:p.name,cellar:p.village,status:b.dataset.action==='producer-wishlist'?'wishlist':'tasted'});break}
 case 'close':$('#editor').close();break;
 case 'site-wine':openWine({site:id});break;
 case 'add-site':openSite();break;
 case 'go-journal-incomplete':tab='journal';wineStatus='tasted';query='';$('#search').value='';render();break;
 case 'edit-site':openSite(state.personalSites.find(x=>x.id===id));break;
 case 'delete-site':{const users=state.wines.filter(w=>w.site===id).length+state.producerSites.filter(l=>l.site===id).length+state.personalSites.filter(x=>x.parent===id).length;if(users){notify('This vineyard is linked to wines, producers or other sites. Unlink those first.');break}if(confirm('Delete this personal vineyard?')){state.personalSites=state.personalSites.filter(x=>x.id!==id);state.targets=state.targets.filter(k=>k.split('|')[2]!=='site:'+id);state.excluded=state.excluded.filter(e=>e.key.split('|')[2]!=='site:'+id);if(mxArea==='site:'+id)mxArea='all';state.explore=state.explore.filter(x=>x!==id);save();render()}break}
 case 'mx-cell':openCell(b.dataset.g,b.dataset.geo,b.dataset.area);break;
 case 'mx-target':{const k=targetKey(b.dataset.g,b.dataset.geo,b.dataset.area);state.targets=state.targets.includes(k)?state.targets.filter(x=>x!==k):[...state.targets,k];save();render();openCell(b.dataset.g,b.dataset.geo,b.dataset.area);break}
 case 'mx-na':{const k=targetKey(b.dataset.g,b.dataset.geo,b.dataset.area);if(state.excluded.some(x=>x.key===k)){state.excluded=state.excluded.filter(x=>x.key!==k)}else{const reason=(prompt('Why is this combination not applicable? A stated reason or evidence is required (a personal exclusion with a source; missing catalogue evidence is not an impossibility).')||'').trim();if(!reason)break;state.excluded=[...state.excluded,{key:k,reason}]}save();render();openCell(b.dataset.g,b.dataset.geo,b.dataset.area);break}
 case 'mx-record':{const a=b.dataset.area;openWine({grape:b.dataset.g==='blend'?'Blend / other':b.dataset.g,site:a.startsWith('site:')?a.slice(5):'',originRegion:a&&!a.startsWith('site:')&&a!=='all'?a:'',status:'tasted'},true,true);break}
 case 'topic-wine':openWine({topics:[id]});break;
 case 'edit-wine':openWine(state.wines.find(w=>w.id===id));break;
 case 'complete-origin':openWine(state.wines.find(w=>w.id===id));break;
 case 'repeat-wine':{const w=state.wines.find(w=>w.id===id);openWine({...w,id:'',date:today(),notes:'',status:'tasted'},true);break}
 case 'legacy-wine':openWine({notes:state.legacy.notes[id]||'',topics:topicById.has(id)?[id]:[]});break;
 case 'explore':state.explore=want(id)?state.explore.filter(x=>x!==id):[...state.explore,id];save();render();break;
 case 'delete-wine':if(state.comparisons.some(c=>c.wines.includes(id))){notify('This wine is linked to a comparison. Edit or delete that comparison first.');break}if(confirm('Delete this wine record?')){state.wines=state.wines.filter(w=>w.id!==id);save();render()}break;
 case 'new-comparison':openComparison(id);break;
 case 'edit-comparison':openComparison(state.comparisons.find(c=>c.id===id).exercise,id);break;
 case 'delete-comparison':if(confirm('Delete this comparison?')){state.comparisons=state.comparisons.filter(c=>c.id!==id);save();render()}break;
 case 'export':download();break;
 case 'copy':try{await navigator.clipboard.writeText(readable());notify('Readable journal copied. Use Export for a restorable backup.')}catch{notify('Clipboard unavailable. Use Export complete backup instead.')}break;
 }
});
// Never overwrite the old key. Old marks are evidence of old actions, not fabricated tasting records.
try{const raw=localStorage.getItem(KEY);if(raw)state=validate(JSON.parse(raw));else{const old=localStorage.getItem(OLD);if(old){state.legacy=legacyValid(JSON.parse(old));save();}}}catch(e){storageWritable=false;notify('Saved data could not be loaded. It has not been overwritten. Export or recover your browser data before continuing.');}
render();
// Listen for another tab’s saves without silently overwriting an open editor.
window.addEventListener('storage',e=>{if(e.key===KEY){storageWritable=false;notify('The journal changed in another tab. Reload before making further edits; saving is paused to protect those changes.');}});
})();
